# Make new-tab behavior explicit without arrow symbols.
import re
for page in D.rglob('*.html'):
    markup=page.read_text()
    def annotate(match):
        attrs, body = match.group(1), match.group(2)
        if 'target="_blank"' not in attrs:
            return match.group(0)
        attrs=re.sub(r'aria-label="([^"]+)"',lambda m:'aria-label="'+m.group(1)+' (opens in a new tab)"',attrs)
        if '<svg' in body:
            body += '<span class="social-tab-note">New tab</span>'
        else:
            body += '<span class="new-tab-label">New tab</span>'
        return '<a'+attrs+'>'+body+'</a>'
    markup=re.sub(r'<a([^>]+)>(.*?)</a>',annotate,markup,flags=re.S)
    page.write_text(markup)
